INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6354783, 940429, 103004, '<td valign="top">Surprise!!! great catch</td>', 'Surprise!!! great catch', '2011-03-17 15:18:55.000000', NULL, 1),
(6354791, 940296, 103004, '<td valign="top">I love this one! good luck</td>', 'I love this one! good luck', '2011-03-17 15:22:37.000000', NULL, 1),
(6354811, 940369, 103004, '<td valign="top">Love it! excellent shot! 10</td>', 'Love it! excellent shot! 10', '2011-03-17 15:29:04.000000', NULL, 1),
(6354848, 939746, 39352, '<td valign="top">The winner, I reckon</td>', 'The winner, I reckon', '2011-03-17 15:43:57.000000', NULL, 1),
(6354898, 940210, 117804, '<td valign="top">I like the lines</td>', 'I like the lines', '2011-03-17 16:26:15.000000', NULL, 1),
(6354938, 940408, 76335, '<td valign="top">A funky scene enhanced by the funkiness of the wide angle lens. It''s a funky word, funky. I don''t mean to overuse it. Great shot.</td>', 'A funky scene enhanced by the funkiness of the wide angle lens. It''s a funky word, funky. I don''t mean to overuse it. Great shot.', '2011-03-17 17:09:40.000000', NULL, 1),
(6354942, 940296, 76335, '<td valign="top">The real poetry is in your timing -- like the way you''ve caught that bird in the lower left so close to landing.</td>', 'The real poetry is in your timing -- like the way you''ve caught that bird in the lower left so close to landing.', '2011-03-17 17:10:59.000000', NULL, 1),
(6354943, 940356, 76335, '<td valign="top">The title and border are kind of unnecesary, but the vantage point here is surprising and fun.</td>', 'The title and border are kind of unnecesary, but the vantage point here is surprising and fun.', '2011-03-17 17:11:43.000000', NULL, 1),
(6354945, 940447, 76335, '<td valign="top">Now THIS is what this challenge is about. THIS is what I wanted to see lots of. Excellent.</td>', 'Now THIS is what this challenge is about. THIS is what I wanted to see lots of. Excellent.', '2011-03-17 17:12:19.000000', NULL, 1),
(6354951, 940542, 76335, '<td valign="top">Now this is interesting. An accidental blossom overlooked amidst the chaos of the city. Very good.</td>', 'Now this is interesting. An accidental blossom overlooked amidst the chaos of the city. Very good.', '2011-03-17 17:14:43.000000', NULL, 1),
(6355028, 939940, 2158, '<td valign="top">No real signs of urban here, but I love it.  I suspect it would have done better for "Birds in flight" though.</td>', 'No real signs of urban here, but I love it.  I suspect it would have done better for "Birds in flight" though.', '2011-03-17 17:52:29.000000', NULL, 1),
(6355051, 940576, 2158, '<td valign="top">Nice take on the challenge, but I''m not sure it wouldn''t be better to crop off the building on the right.</td>', 'Nice take on the challenge, but I''m not sure it wouldn''t be better to crop off the building on the right.', '2011-03-17 18:01:41.000000', NULL, 1),
